<script setup lang="ts">import {ref} from 'vue';import axios from 'axios';const props=defineProps<{id:string}>();const student=ref('00000000-0000-0000-0000-000000000011');const score=ref(0);const machineScore=ref(0);const comment=ref('');const version=ref(0);const status=ref('');async function save(){await axios.put(`/api/v1/teacher/exams/${props.id}/reviews/${student.value}`,{score:score.value,comment:comment.value,version:version.value});version.value++;status.value='成绩与评语修改已成功留痕落库'} </script>
<template><main><h1>试卷人工批改与复核</h1><label>学生学号：<input v-model="student"></label><section><h2>学生源码快照</h2><pre>此处展示不可变交卷快照源码，供教师高亮对比查看。</pre></section><p>机器预判得分：{{machineScore}} 分</p><label>教师最终得分：<input type="number" v-model.number="score" min="0"> 分</label><label>教师评语：</label><textarea v-model="comment" placeholder="请输入教师评语"></textarea><button @click="save">保存评分</button><span class="success">{{status}}</span></main></template><style scoped>main{padding:32px;display:grid;gap:12px;max-width:800px;font:16px system-ui}textarea{min-height:120px;padding:8px}button{width:140px;padding:9px}.success{color:#067647}</style>
